def question_rows():
    result = []
    for (category, difficulty), rows in BANK.items():
        for row in rows:
            index = len(result) + 1
            text, correct, *rest = row
            distractors, explanation = rest[:3], rest[3]
            position = (index - 1) % 4
            options = list(distractors)
            options.insert(position, correct)
            result.append(dict(id=index, category=category, difficulty=difficulty,
                               text=text, options=json.dumps(options, ensure_ascii=False),
                               correct=position, explanation=explanation))
    return result
